def can_partition_k_subsets(nums, k):
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    nums = sorted(nums, reverse=True)
    if nums[0] > target:
        return False
    buckets = [0] * k

    def dfs(i):
        if i == len(nums):
            return True
        tried = set()
        for b in range(k):
            if buckets[b] + nums[i] <= target and buckets[b] not in tried:
                tried.add(buckets[b])
                buckets[b] += nums[i]
                if dfs(i + 1):
                    return True
                buckets[b] -= nums[i]
        return False

    return dfs(0)

def can_partition_k_subsets(nums, k):
    total, n = sum(nums), len(nums)
    if total % k:
        return False
    target = total // k
    fill = [-1] * (1 << n)
    fill[0] = 0
    for mask in range(1 << n):
        if fill[mask] < 0:
            continue
        for i in range(n):
            if not mask >> i & 1 and fill[mask] + nums[i] <= target:
                fill[mask | 1 << i] = (fill[mask] + nums[i]) % target
    return fill[-1] == 0
